import base64, pathlib, sys

BASE = pathlib.Path.home() / 'Downloads' / 'ClearChart'
if not BASE.exists():
    print('ERROR: No encuentro ~/Downloads/ClearChart')
    sys.exit(1)

files = {
    'frontend/app.js': '',
    'frontend/styles.css': '',
    'backend/prompts.py': '',
    'backend/ai_provider.py': '',
}

for rel, b64 in files.items():
    dest = BASE / rel
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(base64.b64decode(b64))
    print(f'  ✔  {rel}')

# Actualizar .env para usar GitHub Models
env_path = BASE / 'backend' / '.env'
if env_path.exists():
    content = env_path.read_text()
    import re
    content = re.sub(r'AI_PROVIDER=.*', 'AI_PROVIDER=github', content)
    env_path.write_text(content)
    print('  ✔  backend/.env (AI_PROVIDER=github)')
else:
    print('  ⚠  No encontré backend/.env — crealo con las instrucciones de abajo')

print()
print('¡Listo! Reiniciá el servidor:')
print('  pkill -f uvicorn; pkill -f "python3 main.py"; cd ~/Downloads/ClearChart/backend && python3 main.py')